package muscleviewer

// figureView is one side of the flat body figure, generated by
// scripts/bodymap into figure_gen.go from the same mesh as body-map.glb, so a
// region's outline here matches its patch of skin on the 3D figure.
type figureView struct {
	ViewBox    string
	Silhouette string // the whole body, drawn first in the untrained colour
	Regions    []figureRegion
}

// figureRegion is one muscle region's outline, as SVG path data (evenodd).
type figureRegion struct {
	Region string
	D      string
}
